def match_parens(lst):
    if len(lst) != 2:
        return 'No'

    for string in lst:
        if not all(char in ['(', ')'] for char in string):
            return 'No'

    concatenated_string = lst[0] + lst[1]

    stack = []
    for char in concatenated_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return 'No'
            stack.pop()

    if not stack:
        return 'Yes'
    else:
        return 'No'

