def smallest_change(arr):
    def is_palindrome(sub_arr):
        return sub_arr == sub_arr[::-1]

    def count_modifications(sub_arr):
        modifications = 0
        for i in range(len(sub_arr) // 2):
            if sub_arr[i] != sub_arr[-i - 1]:
                modifications += 1
        return modifications

    min_modifications = float('inf')
    for i in range(len(arr)):
        for j in range(i, len(arr)):
            sub_arr = arr[i:j+1]
            modifications = count_modifications(sub_arr)
            if modifications < min_modifications:
                min_modifications = modifications

    return min_modifications

