def smallest_change(arr):
    def is_palindromic(sub_arr):
        return sub_arr == sub_arr[::-1]

    def min_changes(sub_arr):
        changes = 0
        left, right = 0, len(sub_arr) - 1
        while left < right:
            if sub_arr[left] != sub_arr[right]:
                changes += 1
            left += 1
            right -= 1
        return changes

    min_changes_required = float('inf')
    for i in range(len(arr)):
        sub_arr = arr[:i] + arr[i+1:]
        if is_palindromic(sub_arr):
            min_changes_required = min(min_changes_required, min_changes(sub_arr))

    return min_changes_required

